'use client';

import { useState, useEffect, useRef } from 'react';
import { useRouter } from 'next/navigation';
import { startAssessment, submitAssessment } from '../../services/api';
import Modal from '../../components/ui/Modal';
import Toast from '../../components/ui/Toast';

export default function AssessmentPage() {

    const router = useRouter();
    const [questions, setQuestions] = useState([]);
    const [answers, setAnswers] = useState([]);
    const [setId, setSetId] = useState(null);
    const [loading, setLoading] = useState(true);
    const [currentPage, setCurrentPage] = useState(0);
    const [isCompleted, setIsCompleted] = useState(false);

    const ITEMS_PER_PAGE = 10;

    // Timer — 45 mins
    const [timeLeft, setTimeLeft] = useState(45 * 60);
    const isSubmitting = useRef(false);

    const [modalConfig, setModalConfig] = useState({ isOpen: false, title: '', message: '' });
    const [showToast, setShowToast] = useState(false);

    // LOAD QUESTIONS
    useEffect(() => {
        const fetchQuestions = async () => {
            const userId = localStorage.getItem("disc_user_id");
            if (!userId) return router.push("/login");
            try {
                const data = await startAssessment(userId);
                setQuestions(data.questions || []);
                setSetId(data.setId);
            } finally {
                setLoading(false);
            }
        };
        fetchQuestions();
    }, []);

    // TIMER
    useEffect(() => {
        if (loading || isCompleted) return;
        if (timeLeft <= 0) return handleSubmit();
        const interval = setInterval(() => setTimeLeft(prev => prev - 1), 1000);
        return () => clearInterval(interval);
    }, [timeLeft, loading, isCompleted]);

    // BLOCK BACK BUTTON
    useEffect(() => {
        if (loading) return;

        window.history.pushState(null, "", window.location.href);
        const blockBack = () => {
            window.history.pushState(null, "", window.location.href);
            setShowToast(true);
        };
        window.addEventListener("popstate", blockBack);

        return () => window.removeEventListener("popstate", blockBack);
    }, [loading]);

    const handleAnswer = (qId, type) => {
        setAnswers(prev => {
            const exists = prev.find(a => a.qId === qId);
            if (exists) return prev.map(a => a.qId === qId ? { qId, answer: type } : a);
            return [...prev, { qId, answer: type }];
        });
    };

    const handleNext = () => {
        const currentSet = questions.slice(currentPage * ITEMS_PER_PAGE, (currentPage + 1) * ITEMS_PER_PAGE);
        const allAnswered = currentSet.every(q => answers.some(a => a.qId === q.qId));

        if (!allAnswered) {
            return setModalConfig({ isOpen: true, title: "Incomplete", message: "Please answer all questions." });
        }
        setCurrentPage(prev => prev + 1);
    };

    const handleSubmit = async () => {
        if (isSubmitting.current) return;
        isSubmitting.current = true;
        setLoading(true);

        try {
            const userId = localStorage.getItem("disc_user_id");
            await submitAssessment(userId, setId, answers);
            setIsCompleted(true);
            window.location.href = "/results";
        } catch (err) {
            console.error(err);
        }
    };

    if (loading) return (
        <div className="min-h-screen flex items-center justify-center bg-black text-white">
            <div className="animate-pulse text-cyan-400">Loading Assessment...</div>
        </div>
    );

    const pageQuestions = questions.slice(currentPage * ITEMS_PER_PAGE, (currentPage + 1) * ITEMS_PER_PAGE);
    const isLastPage = currentPage === Math.ceil(questions.length / ITEMS_PER_PAGE) - 1;
    const progress = (answers.length / questions.length) * 100;

    return (
        <main className="min-h-screen p-5 bg-black text-white overflow-hidden">

            <Toast message="Navigation blocked during assessment." isVisible={showToast} onClose={() => setShowToast(false)} />
            <Modal isOpen={modalConfig.isOpen} onClose={() => setModalConfig({ ...modalConfig, isOpen: false })} title={modalConfig.title} message={modalConfig.message} />

            {/* Header */}
            <div className="flex justify-between items-center mb-6 fade-in-up">
                <h2 className="text-xl font-bold">Assessment</h2>
                <div className="font-mono text-2xl">
                    {Math.floor(timeLeft / 60)}:{String(timeLeft % 60).padStart(2, "0")}
                </div>
            </div>

            {/* Progress Bar */}
            <div className="h-2 bg-zinc-800 rounded-full mb-6">
                <div className="h-full bg-gradient-to-r from-cyan-500 to-blue-600 rounded-full transition-all" style={{ width: `${progress}%` }}></div>
            </div>

            {/* QUESTIONS — Animated Page */}
            <div className="space-y-8 slide-in">
                {pageQuestions.map((q, index) => {
                    const existing = answers.find(a => a.qId === q.qId)?.answer;
                    return (
                        <div key={q.qId} className="fade-in-up" style={{ animationDelay: `${index * 40}ms` }}>
                            <h3 className="text-lg mb-3">{q.qId}. {q.question}</h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                                {q.options.map((opt, i) => (
                                    <button
                                        key={i}
                                        onClick={() => handleAnswer(q.qId, opt.type)}
                                        className={`p-4 rounded-xl border font-semibold transition-all duration-300
                                                ${existing === opt.type
                                                ? "bg-gradient-to-r from-cyan-400 to-blue-500 text-black border-cyan-200 shadow-lg scale-[1.02]"
                                                : "bg-white/10 border-white/20 hover:bg-white/20 hover:scale-[1.01]"
                                            }`}
                                    >
                                        {opt.text}
                                    </button>
                                ))}
                            </div>
                        </div>
                    );
                })}
            </div>

            {/* Navigation */}
            <div className="flex justify-end mt-10">
                {!isLastPage ? (
                    <button onClick={handleNext} className="px-10 py-4 bg-white text-black rounded-xl font-bold hover:scale-105 transition-transform">
                        Next →
                    </button>
                ) : (
                    <button onClick={handleSubmit} className="px-10 py-4 bg-gradient-to-r from-cyan-600 to-blue-600 text-white rounded-xl font-bold hover:scale-105 transition-transform">
                        Submit
                    </button>
                )}
            </div>

        </main>
    );
}
